/* ========== 运行状态 ========== */
const state = {
  status: {},        // stepId -> locked | ready | executing | armed | done
  currentIdx: 0,
  intercepts: 0,
  undoCount: 0,
  confirmCount: 0,
  checked: {},       // stepId -> {index:true}
  observed: {},      // stepId -> true（观察窗口已结束，勾选可见）
  armedStepId: null,
