281	function focusCurrentControl() {
282	  if (state.finished || state.currentIdx < 0) return;
283	  const step = STEPS[state.currentIdx];
284	  const ref = cardRefs[step.id];
285	  if (!ref) return;
286	  ref.card.scrollIntoView({ behavior: "smooth", block: "nearest" });
287	  let target = null;
288	  if (step.kind === "check") {
289	    const enabled = ref.checkInputs.filter(function (i) { return !i.disabled; });
290	    target = enabled[0] || ref.observeButton || null;
291	  } else {
292	    target = ref.button;
293	  }
294	  if (target && !target.disabled) target.focus({ preventScroll: true });
295	}
296	
297	/* ========== 动作类步骤（模拟执行） ========== */
298	function runAction(step) {
299	  const ref = cardRefs[step.id];
300	  state.status[step.id] = "executing";
301	  audit("execute", "执行：" + step.title);
302	  if (ref.progress) {
303	    ref.progress.style.transition = "none";
304	    ref.progress.style.width = "0%";
305	    void ref.progress.offsetWidth;
306	    ref.progress.style.transition = "width " + step.simulateMs + "ms linear";
307	    ref.progress.style.width = "100%";
308	  }
309	  renderAll();
310	  setTimeout(function () {
311	    if (state.status[step.id] !== "executing") return;
