832	    const done = steps.filter(function (s) { return state.status[s.id] === "done"; }).length;
833	    refObj.sub.textContent = done + " / " + steps.length + " 步";
834	    refObj.btn.classList.toggle("done", done === steps.length);
835	    const hasCurrent = steps.some(function (s) { return STEPS[state.currentIdx] && STEPS[state.currentIdx].id === s.id; });
836	    refObj.btn.classList.toggle("active", hasCurrent);
837	  });
838	}
