840	function renderSummary() {
841	  const ok = state.intercepts === 0;
842	  const used = fmtClock(elapsedMs());
843	  const evCount = auditFeedEl.children.length;
844	  summarySlotEl.innerHTML = "";
845	  const sec = el("section", "summary-card" + (ok ? "" : " flawed"));
846	
847	  const badge = el("div", "sum-badge", ok ? "零失误" : (state.intercepts + " 次拦截"));
848	  sec.appendChild(badge);
849	
850	  const wrap = el("div");
851	  wrap.appendChild(el("h2", null, ok ? "发布流程全程完成 · 零失误" : "发布流程全程完成"));
852	  wrap.appendChild(el("p", null, ok
853	    ? "订单服务 v2.7.0 已在生产环境落定：全部 " + TOTAL + " 步按序完成，未触发任何守卫拦截。"
854	    : "订单服务 v2.7.0 已落定，但过程中有 " + state.intercepts + " 次风险操作被顺序守卫拦截并留痕。"));
855	  const stats = el("div", "sum-stats");
856	  [["总用时", used],
857	   ["不可逆确认", state.confirmCount + " 次"],
858	   ["恢复窗口撤销", state.undoCount + " 次"],
859	   ["风险拦截", state.intercepts + " 次"],
860	   ["审计事件", evCount + " 条"]].forEach(function (p) {
861	    const s = el("div", "sum-stat");
862	    s.appendChild(el("b", null, p[1]));
863	    s.appendChild(document.createTextNode(p[0]));
864	    stats.appendChild(s);
865	  });
866	  wrap.appendChild(stats);
867	  sec.appendChild(wrap);
868	  summarySlotEl.appendChild(sec);
869	}
