871	/* ========== 初始化 / 重置 ========== */
872	function resetCoreState() {
873	  STEPS.forEach(function (st) { state.status[st.id] = "locked"; });
874	  state.currentIdx = 0;
875	  state.intercepts = 0;
876	  state.undoCount = 0;
877	  state.confirmCount = 0;
878	  state.checked = {};
879	  state.observed = {};
880	  state.armedStepId = null;
881	  state.armedRemain = 0;
882	  state.finished = false;
883	  state.startedAt = performance.now();
884	  state.finishedAt = 0;
885	  refreshOrderStatuses();
886	}
