888	function buildAll() {
889	  buildPhaseNav();
890	  buildStepList();
891	  auditFeedEl.innerHTML = "";
892	  summarySlotEl.innerHTML = "";
893	  audit("system", "发布窗口开启：流程就绪，共 " + TOTAL + " 步（含 " + IRREVERSIBLE_COUNT + " 步不可逆操作）");
894	  renderAll();
895	}
896	
897	function resetAll() {
898	  resetCoreState();
899	  buildAll();
900	  toast("演练已重置：流程回到初始就绪态", false);
901	  const first = cardRefs[STEPS[0].id];
902	  if (first && first.checkInputs[0]) first.checkInputs[0].focus({ preventScroll: true });
903	}
