905	/* 全局时钟：演练用时 + 恢复窗口倒计时 */
906	setInterval(function () {
907	  elapsedEl.textContent = fmtClock(elapsedMs());
908	  if (state.armedStepId) {
909	    state.armedRemain = Math.max(0, state.armedRemain - 0.1);
910	    const ref = cardRefs[state.armedStepId];
911	    if (ref && ref.remainText) {
912	      ref.remainText.textContent = "剩余 " + state.armedRemain.toFixed(1) + " 秒";
913	      const step = STEPS.filter(function (s) { return s.id === state.armedStepId; })[0];
914	      if (step && ref.remainBar) {
915	        ref.remainBar.style.width = (state.armedRemain / step.recoverySeconds * 100) + "%";
916	      }
917	    }
918	    if (state.armedRemain <= 0) settleArmed();
919	  }
920	}, 100);
921	
922	resetBtn.addEventListener("click", openResetModal);
923	
924	/* 启动：初始数据内联，脚本执行完毕即完成首屏渲染（就绪态） */
925	resetCoreState();
926	buildAll();
