928	/* ========== 演示钩子：?demo=… 驱动与真实交互完全相同的代码路径，
929	   供截图取证与验收测量使用；正常使用不受影响。 ========== */
930	function demoHook() {
931	  const mode = new URLSearchParams(location.search).get("demo");
932	  if (!mode) return;
933	  const byId = function (id) { return STEPS.filter(function (s) { return s.id === id; })[0]; };
934	  if (mode === "confirm") {
935	    openConfirmModal(byId("s6"));
936	  } else if (mode === "armed") {
937	    executeIrreversible(byId("s6"));
938	  } else if (mode === "intercept") {
939	    intercept(byId("s4"), "顺序守卫：需先完成「" + byId("s1").title + "」");
940	  } else if (mode === "done") {
941	    STEPS.forEach(function (st) {
942	      if (st.kind === "check") {
943	        state.checked[st.id] = {};
944	        st.checks.forEach(function (_t, i) { state.checked[st.id][i] = true; });
945	        if (st.observe) state.observed[st.id] = true;
946	      }
947	      if (st.kind === "irreversible") {
948	        state.confirmCount++;
949	        state.status[st.id] = "done";
950	        audit("confirm", "确认执行：" + st.title + "（变更单 " + FLOW.ticket + "）");
951	        audit("done", st.settleText);
952	      } else {
953	        state.status[st.id] = "done";
954	        audit("done", "完成：" + st.title);
955	      }
956	    });
957	    refreshOrderStatuses();
958	    renderAll();
959	    if (state.finished) finishFlow();
960	  }
961	}
962	demoHook();
963	
964	})();
