          understandings: [
            "我已确认核心指标均在基线以内",
            "我已知晓落定后回退需走完整回滚流程"
          ],
          confirmExpect: "CHG-2417",
          recoverySeconds: 8,
          undoText: "已撤销：重新进入冻结状态（恢复窗口内回退）",
          settleText: "落定生效：版本 v2.7.0 已落定",
          rollbackPlan: "落定后回滚：执行 ROLLBACK-2417 全量预案并发布公告，预计 15 分钟恢复。"
        },
        {
          id: "s10", kind: "check",
          title: "归档发布记录并宣告完成",
          desc: "全程留痕归档，向相关方宣告发布完成。",
          checks: [
            "发布记录已归档至 CHANGELOG",
            "已在 #ops 频道宣告发布完成"
          ]
        }
      ]
    }
  ]
