/* ============================================================
   发布指挥台 · 设计 token（自建轻量设计系统基座）
   ============================================================ */
:root {
  --bg: #f4f6f9;
  --surface: #ffffff;
  --surface-2: #fafbfd;
  --ink: #1a2533;
  --muted: #5c6b7f;
  --faint: #8a97a8;
  --line: #e3e8ef;
  --line-strong: #c9d3e0;

  --brand: #2b5fd9;
  --brand-ink: #1e46a8;
  --brand-soft: #e9effc;
  --brand-line: #b9cbf2;

  --ok: #0e7a55;
  --ok-soft: #e4f5ed;
  --ok-line: #a9dcc4;

  --warn: #b45309;
  --warn-ink: #8a3e06;
  --warn-soft: #fdf3e3;
  --warn-line: #f0cd96;

  --danger: #b3261e;
  --danger-soft: #fdecea;
  --danger-line: #f2b8b5;

  --radius: 14px;
  --radius-s: 9px;
  --shadow: 0 1px 2px rgba(16, 24, 40, .05), 0 6px 20px rgba(16, 24, 40, .07);
  --shadow-pop: 0 8px 40px rgba(16, 24, 40, .18);

  --font: system-ui, "Segoe UI", "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif;
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

/* 可见焦点（键盘可达性） */
:focus-visible {
  outline: 3px solid var(--brand);
  outline-offset: 2px;
  border-radius: 6px;
}

/* ============================================================
   页头
   ============================================================ */
.app-header {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 18px 32px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 40;
}

.brand { display: flex; align-items: center; gap: 12px; min-width: 210px; }
.brand-text h1 { margin: 0; font-size: 18px; letter-spacing: .02em; }
.brand-text p { margin: 0; font-size: 12px; color: var(--muted); }

.flow-meta { flex: 1; min-width: 0; }
.flow-title { display: flex; align-items: center; gap: 10px; margin-bottom: 7px; }
.flow-name { font-weight: 600; font-size: 15px; }
.ticket {
  font-family: ui-monospace, Consolas, monospace;
  font-size: 12px;
  background: var(--brand-soft);
  color: var(--brand-ink);
  border: 1px solid var(--brand-line);
  border-radius: 999px;
  padding: 1px 10px;
}

.progress-row { display: flex; align-items: center; gap: 12px; }
.progress-text { font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.progress-bar {
  flex: 1;
  max-width: 460px;
  height: 8px;
  background: var(--line);
  border-radius: 999px;
  overflow: hidden;
}
.progress-fill {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--brand), #4f80ec);
  border-radius: 999px;
  transition: width .45s ease;
}
.elapsed { font-size: 12.5px; color: var(--faint); font-variant-numeric: tabular-nums; }

/* ============================================================
   布局
   ============================================================ */
.layout {
  display: grid;
  grid-template-columns: 218px minmax(0, 1fr) 316px;
  gap: 24px;
  max-width: 1560px;
  margin: 0 auto;
  padding: 24px 32px 64px;
  align-items: start;
}

/* ============================================================
   左栏 · 阶段导航
   ============================================================ */
.phase-rail { position: sticky; top: 96px; }
.phase-rail h2 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: .14em;
  color: var(--faint);
  margin: 4px 0 14px 4px;
}
.phase-nav { display: flex; flex-direction: column; }

.phase-item {
  position: relative;
  display: block;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  font: inherit;
  color: inherit;
  padding: 12px 14px 12px 34px;
  border-radius: var(--radius-s);
  cursor: pointer;
}
.phase-item::before {          /* 竖向连接线 */
  content: "";
  position: absolute;
  left: 17px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--line);
}
.phase-item:first-child::before { top: 50%; }
.phase-item:last-child::before { bottom: 50%; }

.phase-dot {
  position: absolute;
  left: 11px;
  top: 50%;
  transform: translateY(-50%);
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--surface);
  border: 2px solid var(--line-strong);
  z-index: 1;
}
.phase-item.done .phase-dot { background: var(--ok); border-color: var(--ok); }
.phase-item.active .phase-dot {
  background: var(--brand);
  border-color: var(--brand);
  box-shadow: 0 0 0 4px var(--brand-soft);
}

.phase-name { display: block; font-weight: 600; font-size: 14px; }
.phase-sub { display: block; font-size: 12px; color: var(--muted); margin-top: 1px; font-variant-numeric: tabular-nums; }
.phase-item.active { background: var(--brand-soft); }
.phase-item.done .phase-sub { color: var(--ok); }

/* ============================================================
   中栏 · 步骤列表
   ============================================================ */
.step-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 14px; }

.phase-heading {
  margin: 18px 0 2px 2px;
  font-size: 13px;
  color: var(--muted);
  font-weight: 600;
  letter-spacing: .04em;
  scroll-margin-top: 100px;
}
.phase-heading:first-child { margin-top: 0; }

.step-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 18px 22px;
  scroll-margin-top: 96px;
  transition: border-color .25s ease, box-shadow .25s ease, opacity .25s ease;
}

.step-card.locked { opacity: .62; background: var(--surface-2); cursor: not-allowed; }
.step-card.current { border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-soft), var(--shadow); }
.step-card.done { background: var(--surface-2); }
.step-card.done .step-title { color: var(--muted); }

.step-card.irreversible { border-left: 4px solid var(--warn); }
.step-card.armed {
  border-color: var(--warn-line);
  box-shadow: 0 0 0 3px var(--warn-soft), var(--shadow);
  animation: armed-pulse 1.6s ease-in-out infinite;
}
@keyframes armed-pulse {
  0%, 100% { box-shadow: 0 0 0 3px rgba(240, 205, 150, .55), var(--shadow); }
  50%      { box-shadow: 0 0 0 7px rgba(240, 205, 150, .30), var(--shadow); }
}
.step-card.flash { animation: flash-red .5s ease; }
@keyframes flash-red {
  0% { border-color: var(--danger); box-shadow: 0 0 0 4px var(--danger-soft); }
  100% { }
}

.step-head { display: flex; align-items: flex-start; gap: 14px; }

.step-no {
  flex: none;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 13.5px;
  font-weight: 700;
  background: var(--line);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.step-card.current .step-no { background: var(--brand); color: #fff; }
.step-card.done .step-no { background: var(--ok); color: #fff; }
.step-card.armed .step-no { background: var(--warn); color: #fff; }

.step-titles { flex: 1; min-width: 0; }
.step-title { margin: 2px 0 3px; font-size: 15.5px; font-weight: 650; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.step-desc { margin: 0; font-size: 13px; color: var(--muted); max-width: 62ch; }

.kind-badge {
  font-size: 11px;
  font-weight: 600;
  border-radius: 999px;
  padding: 1.5px 9px;
  letter-spacing: .03em;
}
.kind-check   { background: var(--surface-2); color: var(--muted); border: 1px solid var(--line-strong); }
.kind-action  { background: var(--brand-soft); color: var(--brand-ink); border: 1px solid var(--brand-line); }
.kind-irrev   { background: var(--warn-soft); color: var(--warn-ink); border: 1px solid var(--warn-line); }

.status-chip {
  flex: none;
  font-size: 12px;
  font-weight: 600;
  border-radius: 999px;
  padding: 3px 12px;
  font-variant-numeric: tabular-nums;
}
.st-locked    { background: var(--surface-2); color: var(--faint); border: 1px solid var(--line); }
.st-ready     { background: var(--brand-soft); color: var(--brand-ink); border: 1px solid var(--brand-line); }
.st-executing { background: var(--brand); color: #fff; }
.st-armed     { background: var(--warn); color: #fff; }
.st-done      { background: var(--ok-soft); color: var(--ok); border: 1px solid var(--ok-line); }

.step-body { margin-top: 14px; padding-left: 44px; }

.guard-reason {
  display: none;
  margin-top: 10px;
  padding: 7px 12px;
  font-size: 12.5px;
  color: var(--faint);
  background: var(--surface-2);
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-s);
}
.step-card.locked .guard-reason { display: block; }

/* 核对项 */
.check-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.check-item { display: flex; align-items: center; gap: 10px; }
.check-item input[type="checkbox"] {
  width: 17px; height: 17px;
  accent-color: var(--brand);
  cursor: pointer;
}
.check-item input[type="checkbox"]:disabled { cursor: not-allowed; }
.check-item label { font-size: 13.5px; cursor: pointer; }
.check-item input[type="checkbox"]:disabled + label { cursor: not-allowed; color: var(--faint); }
.check-item.checked label { color: var(--muted); text-decoration: line-through; text-decoration-color: var(--ok-line); }

/* 操作按钮 */
.btn {
  font: inherit;
  font-weight: 600;
  font-size: 13.5px;
  border-radius: 10px;
  padding: 9px 18px;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background .18s ease, border-color .18s ease, transform .06s ease;
}
.btn:active { transform: translateY(1px); }
.btn:disabled { cursor: not-allowed; opacity: .55; }

.btn.primary { background: var(--brand); color: #fff; }
.btn.primary:hover:not(:disabled) { background: var(--brand-ink); }
.btn.ghost { background: var(--surface); border-color: var(--line-strong); color: var(--muted); }
.btn.ghost:hover:not(:disabled) { border-color: var(--faint); color: var(--ink); }
.btn.warn-solid { background: var(--warn); color: #fff; }
.btn.warn-solid:hover:not(:disabled) { background: var(--warn-ink); }
.btn.danger { background: var(--danger); color: #fff; }
.btn.danger:hover:not(:disabled) { background: #8f1d17; }

.action-note { margin: 10px 0 0; font-size: 12.5px; color: var(--muted); }
.action-note.ok { color: var(--ok); }

/* 执行中进度条 */
.inline-progress {
  height: 6px; border-radius: 999px; background: var(--line);
  overflow: hidden; margin-top: 12px; max-width: 420px;
}
.inline-progress > div {
  height: 100%; width: 0%;
  background: var(--brand);
  transition: width .2s linear;
}

/* 指标行（观察步骤） */
.metric-list { list-style: none; margin: 10px 0 0; padding: 0; display: flex; gap: 12px; flex-wrap: wrap; }
.metric-chip {
  font-size: 12.5px;
  background: var(--ok-soft);
  border: 1px solid var(--ok-line);
  color: var(--ok);
  border-radius: var(--radius-s);
  padding: 5px 12px;
  font-variant-numeric: tabular-nums;
}
.metric-chip b { font-weight: 700; }

/* 恢复窗口 */
.recovery-box {
  margin-top: 12px;
  border: 1px solid var(--warn-line);
  background: var(--warn-soft);
  border-radius: var(--radius-s);
  padding: 13px 16px;
  display: none;
}
.step-card.armed .recovery-box { display: block; }
.recovery-top { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.recovery-title { font-weight: 700; font-size: 13.5px; color: var(--warn-ink); }
.recovery-count { font-size: 13px; color: var(--warn-ink); font-variant-numeric: tabular-nums; }
.recovery-count b { font-size: 16px; }
.recovery-bar { flex: 1; min-width: 120px; max-width: 260px; height: 6px; background: #efd9b4; border-radius: 999px; overflow: hidden; }
.recovery-bar > div { height: 100%; background: var(--warn); border-radius: 999px; }
.recovery-hint { margin: 8px 0 0; font-size: 12.5px; color: var(--warn-ink); }

/* 回滚预案（details） */
.rollback { margin-top: 12px; font-size: 13px; }
.rollback summary {
  cursor: pointer;
  color: var(--brand-ink);
  font-weight: 600;
  width: fit-content;
  border-radius: 6px;
  padding: 2px 4px;
  list-style-position: inside;
}
.rollback p {
  margin: 8px 0 0;
  color: var(--muted);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-s);
  padding: 10px 14px;
  max-width: 66ch;
}

/* ============================================================
   完成态总结
   ============================================================ */
.summary-card {
  background: var(--surface);
  border: 1px solid var(--ok-line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 26px 30px;
  margin-bottom: 18px;
  display: flex;
  gap: 24px;
  align-items: center;
}
.summary-card .sum-badge {
  flex: none;
  width: 86px; height: 86px;
  border-radius: 50%;
  display: grid; place-items: center;
  text-align: center;
  font-weight: 800;
  font-size: 17px;
  line-height: 1.25;
  background: var(--ok-soft);
  color: var(--ok);
  border: 3px solid var(--ok);
}
.summary-card.flawed .sum-badge { background: var(--warn-soft); color: var(--warn-ink); border-color: var(--warn); }
.summary-card h2 { margin: 0 0 6px; font-size: 19px; }
.summary-card p { margin: 0 0 10px; color: var(--muted); font-size: 13.5px; max-width: 70ch; }
.sum-stats { display: flex; gap: 22px; flex-wrap: wrap; }
.sum-stat { font-size: 12.5px; color: var(--faint); }
.sum-stat b { display: block; font-size: 19px; color: var(--ink); font-variant-numeric: tabular-nums; }

/* ============================================================
   右栏 · 零失误 + 审计
   ============================================================ */
.side-rail { position: sticky; top: 96px; display: flex; flex-direction: column; gap: 16px; }

.zero-panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 18px 22px;
  text-align: center;
}
.zero-num { font-size: 42px; font-weight: 800; line-height: 1.1; color: var(--ok); font-variant-numeric: tabular-nums; }
.zero-num.flawed { color: var(--warn); }
.zero-label { font-weight: 600; font-size: 13.5px; margin-top: 2px; }
.zero-hint { font-size: 12px; color: var(--faint); margin-top: 4px; }

.audit-panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px 18px;
}
.audit-panel h2 {
  margin: 2px 4px 10px;
  font-size: 13px;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--faint);
}
.audit-feed { list-style: none; margin: 0; padding: 0; max-height: 560px; overflow: auto; display: flex; flex-direction: column; gap: 2px; }
.ev {
  display: flex;
  gap: 8px;
  align-items: baseline;
  padding: 6px 8px;
  border-radius: 8px;
  font-size: 12.5px;
}
.ev:nth-child(odd) { background: var(--surface-2); }
.ev-t { flex: none; color: var(--faint); font-variant-numeric: tabular-nums; font-size: 11.5px; }
.ev-tag {
  flex: none;
  font-size: 10.5px;
  font-weight: 700;
  border-radius: 5px;
  padding: 0 6px;
  letter-spacing: .04em;
}
.ev-system    .ev-tag { background: var(--line); color: var(--muted); }
.ev-execute   .ev-tag { background: var(--brand-soft); color: var(--brand-ink); }
.ev-confirm   .ev-tag { background: var(--brand-soft); color: var(--brand-ink); }
.ev-undo      .ev-tag { background: var(--warn-soft); color: var(--warn-ink); }
.ev-intercept .ev-tag { background: var(--danger); color: #fff; }
.ev-done      .ev-tag { background: var(--ok); color: #fff; }
.ev-intercept .ev-text { color: var(--danger); font-weight: 600; }
.ev-text { color: var(--ink); }

/* ============================================================
   Toast
   ============================================================ */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: #fff;
  font-size: 13.5px;
  padding: 11px 20px;
  border-radius: 12px;
  box-shadow: var(--shadow-pop);
  opacity: 0;
  pointer-events: none;
  transition: opacity .22s ease, transform .22s ease;
  max-width: 560px;
  z-index: 90;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast.danger { background: var(--danger); }

/* ============================================================
   模态 · 确认关卡
   ============================================================ */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(18, 26, 38, .46);
  display: grid;
  place-items: center;
  z-index: 100;
  animation: fade-in .18s ease;
}
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }

.modal {
  background: var(--surface);
  border-radius: 18px;
  box-shadow: var(--shadow-pop);
  width: min(600px, calc(100vw - 48px));
  max-height: calc(100vh - 64px);
  overflow: auto;
  padding: 26px 30px;
  animation: pop-in .2s ease;
}
@keyframes pop-in { from { transform: translateY(10px) scale(.985); opacity: .6; } to { transform: none; opacity: 1; } }

.modal h3 { margin: 0 0 4px; font-size: 18px; }
.m-kind { margin: 0 0 16px; font-size: 12.5px; color: var(--warn-ink); font-weight: 600; }
.m-section { margin: 0 0 16px; }
.m-section h4 {
  margin: 0 0 6px;
  font-size: 12px;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--faint);
}
.m-consequence {
  background: var(--danger-soft);
  border: 1px solid var(--danger-line);
  border-radius: var(--radius-s);
  padding: 12px 16px;
  font-size: 13.5px;
  color: #7a1712;
}
.m-understand { border: 1px solid var(--line); border-radius: var(--radius-s); padding: 12px 16px 14px; margin: 0; }
.m-understand legend { font-size: 12px; letter-spacing: .1em; text-transform: uppercase; color: var(--faint); padding: 0 6px; }
.m-understand .check-item { padding: 4px 0; }

.m-input label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; }
.m-input code {
  font-family: ui-monospace, Consolas, monospace;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: 0 5px;
}
.m-input input {
  width: 100%;
  font: inherit;
  font-family: ui-monospace, Consolas, monospace;
  font-size: 14px;
  padding: 9px 13px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
}
.m-input input:focus-visible { outline-offset: 0; }
.m-input .m-input-hint { margin: 6px 0 0; font-size: 12px; color: var(--faint); }

.m-rollback { background: var(--warn-soft); border: 1px solid var(--warn-line); border-radius: var(--radius-s); padding: 12px 16px; }
.m-rollback p { margin: 0; font-size: 13px; color: var(--warn-ink); }

.m-actions { display: flex; justify-content: flex-end; gap: 12px; margin-top: 22px; }

/* 重置确认弹窗微调 */
.modal.reset-modal .m-consequence { background: var(--danger-soft); }

/* ============================================================
   响应式（桌面优先，窄屏降级为单列）
   ============================================================ */
@media (max-width: 1180px) {
  .layout { grid-template-columns: 200px minmax(0, 1fr); }
  .side-rail { grid-column: 1 / -1; position: static; }
}
@media (max-width: 860px) {
  .layout { grid-template-columns: 1fr; }
  .phase-rail { position: static; }
  .app-header { flex-wrap: wrap; gap: 12px; }
}

input.old_string:
.check-item input[type="checkbox"] {
  width: 17px; height: 17px;
  accent-color: var(--brand);
  cursor: pointer;
}

input.new_string:
.check-item input[type="checkbox"] {
  width: 24px; height: 24px;
  accent-color: var(--brand);
  cursor: pointer;
  flex: none;
}

