197	function fmtClock(ms) {
198	  const s = Math.max(0, Math.floor(ms / 1000));
199	  return String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
200	}
201	function elapsedMs() { return (state.finishedAt || performance.now()) - state.startedAt; }
202	function el(tag, cls, text) {
203	  const n = document.createElement(tag);
204	  if (cls) n.className = cls;
205	  if (text != null) n.textContent = text;
206	  return n;
207	}
