210	function audit(kind, text) {
211	  const t = fmtClock(elapsedMs());
212	  const li = el("li", "ev ev-" + kind);
213	  li.appendChild(el("span", "ev-t", t));
214	  li.appendChild(el("span", "ev-tag", AUDIT_TAGS[kind] || kind));
215	  li.appendChild(el("span", "ev-text", text));
216	  auditFeedEl.prepend(li);
217	  while (auditFeedEl.children.length > 60) auditFeedEl.removeChild(auditFeedEl.lastChild);
