229	/* ========== 顺序守卫：派生步骤状态 ========== */
230	function refreshOrderStatuses() {
231	  let cur = -1;
232	  for (let i = 0; i < TOTAL; i++) {
233	    if (state.status[STEPS[i].id] !== "done") { cur = i; break; }
234	  }
235	  state.currentIdx = cur;
236	  STEPS.forEach(function (st, i) {
237	    const s = state.status[st.id];
238	    if (s === "executing" || s === "armed" || s === "done") return;
239	    state.status[st.id] = (i === cur) ? "ready" : "locked";
240	  });
241	  state.finished = (cur === -1);
242	}
