481	function escListener(e) {
482	  if (!state.modalOpen) return;
483	  if (e.key === "Escape") {
484	    const cancel = modalRootEl.querySelector(".m-actions .btn.ghost");
485	    if (cancel) cancel.click();
486	  } else if (e.key === "Tab") {
487	    /* 焦点圈：模态打开时 Tab 循环限制在对话框内 */
488	    const focusables = modalRootEl.querySelectorAll("button, input");
489	    if (!focusables.length) return;
490	    const first = focusables[0];
491	    const last = focusables[focusables.length - 1];
492	    if (e.shiftKey && document.activeElement === first) { last.focus(); e.preventDefault(); }
493	    else if (!e.shiftKey && document.activeElement === last) { first.focus(); e.preventDefault(); }
494	  }
495	}
