701	      "窗口落定后本步骤生效；落定前可一键撤销并恢复到执行前状态。"));
702	    body.appendChild(rec);
703	
704	    ref.button = btn;
705	    ref.remainText = remain;
706	    ref.remainBar = barFill;
707	    ref.undoBtn = undoBtn;
708	  }
709	
710	  li.appendChild(body);
711	
712	  const reason = el("div", "guard-reason", "");
713	  li.appendChild(reason);
714	  ref.reason = reason;
715	
716	  li.addEventListener("click", function (e) {
717	    if (state.finished) return;
718	    if (state.status[step.id] !== "locked") return;
719	    const cur = STEPS[state.currentIdx];
720	    if (!cur) return;
721	    const curStatus = state.status[cur.id];
722	    let reasonText;
723	    if (curStatus === "armed") reasonText = "恢复窗口进行中：先撤销或等待「" + cur.title + "」落定";
724	    else if (curStatus === "executing") reasonText = "当前步骤执行中：等待「" + cur.title + "」完成";
725	    else reasonText = "顺序守卫：需先完成「" + cur.title + "」";
726	    intercept(step, reasonText);
727	  });
728	
729	  stepListEl.appendChild(li);
730	  cardRefs[step.id] = ref;
731	}
732	
733	function buildStepList() {
734	  stepListEl.innerHTML = "";
735	  let idx = 0;
736	  FLOW.phases.forEach(function (ph) {
737	    const heading = el("li", "phase-heading", ph.name);
738	    heading.setAttribute("data-phase-heading", ph.id);
739	    stepListEl.appendChild(heading);
740	    ph.steps.forEach(function (st) {
741	      buildStepCard(st, idx);
742	      idx++;
743	    });
744	  });
745	}
746	
747	function onCheckChange(step, ci, input) {
748	  const status = state.status[step.id];
749	  if (status !== "ready" || state.finished) { input.checked = !!state.checked[step.id]?.[ci]; return; }
750	  if (!state.checked[step.id]) state.checked[step.id] = {};
751	  state.checked[step.id][ci] = input.checked;
752	  cardRefs[step.id].checkItems[ci].classList.toggle("checked", input.checked);
753	  const all = step.checks.every(function (_t, i) { return state.checked[step.id][i]; });
754	  if (all) {
755	    const n = Object.keys(state.checked[step.id]).length;
756	    completeStep(step, "完成：" + step.title + "（" + n + " 项核对通过）");
757	  }
758	}
759	
760	/* ========== 渲染 ========== */
761	const CHIP_CLS = { locked: "st-locked", ready: "st-ready", executing: "st-executing", armed: "st-armed", done: "st-done" };
762	const CHIP_TXT = { locked: "按序等待", ready: "可执行", executing: "执行中…", armed: "恢复窗口", done: "已完成" };
763	const REASON_TXT = {
764	  locked: "按序等待", ready: "当前步骤：完成它以解锁后续步骤",
765	  executing: "执行中，请稍候", armed: "恢复窗口倒计时中", done: "已完成并留痕"
766	};
767	
768	function renderAll() { renderSteps(); renderSideAndHeader(); renderPhaseNav(); }
769	
770	function renderSteps() {
771	  STEPS.forEach(function (step, i) {
772	    const ref = cardRefs[step.id];
773	    const status = state.status[step.id] || "locked";
774	    ref.card.className = "step-card" +
775	      (status === "locked" ? " locked" : "") +
776	      (step.kind === "irreversible" ? " irreversible" : "") +
777	      (status === "armed" ? " armed" : "") +
778	      (status === "done" ? " done" : "") +
779	      (i === state.currentIdx && !state.finished ? " current" : "");
780	
781	    ref.chip.className = "status-chip " + CHIP_CLS[status];
782	    ref.chip.textContent = CHIP_TXT[status];
783	
784	    const cur = STEPS[state.currentIdx];
785	    if (status === "locked") {
786	      const curStatus = cur ? state.status[cur.id] : null;
787	      let t = "按序等待：先完成「" + (cur ? cur.title : "") + "」";
788	      if (curStatus === "armed") t = "恢复窗口进行中：等待「" + cur.title + "」撤销或落定";
789	      else if (curStatus === "executing") t = "执行中：等待「" + cur.title + "」完成";
790	      ref.reason.textContent = t;
791	    } else {
792	      ref.reason.textContent = REASON_TXT[status];
793	    }
794	
795	    const isReady = status === "ready";
796	    if (step.kind === "check") {
797	      const canCheck = isReady && (!step.observe || state.observed[step.id]);
798	      ref.checkInputs.forEach(function (input) { input.disabled = !canCheck; });
799	      if (ref.observeButton) {
800	        ref.observeButton.disabled = !isReady || !!state.observed[step.id];
801	        ref.observeButton.textContent = state.observed[step.id] ? "观察完成" : step.observe.buttonLabel;
802	        ref.observeButton.classList.toggle("primary", !state.observed[step.id]);
803	      }
804	    } else if (ref.button) {
805	      ref.button.disabled = !isReady;
806	      if (ref.progress) {
807	        ref.progress.parentElement.style.display = (status === "executing") ? "block" : "none";
808	      }
809	    }
810	    if (ref.rollback) ref.rollback.tabIndex = isReady ? 0 : -1;
811	    if (ref.undoBtn) ref.undoBtn.disabled = status !== "armed";
812	  });
813	}
814	
815	function renderSideAndHeader() {
816	  const doneCount = STEPS.filter(function (s) { return state.status[s.id] === "done"; }).length;
817	  progressTextEl.textContent = doneCount + " / " + TOTAL + " 步";
818	  progressBarEl.setAttribute("aria-valuenow", String(doneCount));
819	  progressFillEl.style.width = (doneCount / TOTAL * 100) + "%";
820	
821	  interceptCountEl.textContent = String(state.intercepts);
822	  interceptCountEl.classList.toggle("flawed", state.intercepts > 0);
823	  if (state.finished) {
824	    zeroHintEl.textContent = state.intercepts === 0
825	      ? "零失误走完全程 ✓"
826	      : "完成，但过程中有 " + state.intercepts + " 次风险操作被拦截";
827	  } else {
828	    zeroHintEl.textContent = "顺序守卫与确认关卡运行中";
829	  }
830	}
831	
832	function renderPhaseNav() {
833	  phaseRefs.forEach(function (refObj) {
834	    const steps = refObj.phase.steps;
835	    const done = steps.filter(function (s) { return state.status[s.id] === "done"; }).length;
836	    refObj.sub.textContent = done + " / " + steps.length + " 步";
837	    refObj.btn.classList.toggle("done", done === steps.length);
838	    const hasCurrent = steps.some(function (s) { return STEPS[state.currentIdx] && STEPS[state.currentIdx].id === s.id; });
839	    refObj.btn.classList.toggle("active", hasCurrent);
840	  });
841	}
842	
843	function renderSummary() {
844	  const ok = state.intercepts === 0;
845	  const used = fmtClock(elapsedMs());
846	  const evCount = auditFeedEl.children.length;
847	  summarySlotEl.innerHTML = "";
848	  const sec = el("section", "summary-card" + (ok ? "" : " flawed"));
849	
850	  const badge = el("div", "sum-badge", ok ? "零失误" : (state.intercepts + " 次拦截"));
851	  sec.appendChild(badge);
852	
853	  const wrap = el("div");
854	  wrap.appendChild(el("h2", null, ok ? "发布流程全程完成 · 零失误" : "发布流程全程完成"));
855	  wrap.appendChild(el("p", null, ok
856	    ? "订单服务 v2.7.0 已在生产环境落定：全部 " + TOTAL + " 步按序完成，未触发任何守卫拦截。"
857	    : "订单服务 v2.7.0 已落定，但过程中有 " + state.intercepts + " 次风险操作被顺序守卫拦截并留痕。"));
858	  const stats = el("div", "sum-stats");
859	  [["总用时", used],
860	   ["不可逆确认", state.confirmCount + " 次"],
861	   ["恢复窗口撤销", state.undoCount + " 次"],
862	   ["风险拦截", state.intercepts + " 次"],
863	   ["审计事件", evCount + " 条"]].forEach(function (p) {
864	    const s = el("div", "sum-stat");
865	    s.appendChild(el("b", null, p[1]));
866	    s.appendChild(document.createTextNode(p[0]));
867	    stats.appendChild(s);
868	  });
869	  wrap.appendChild(stats);
870	  sec.appendChild(wrap);
871	  summarySlotEl.appendChild(sec);
872	}
873	
874	/* ========== 初始化 / 重置 ========== */
875	function resetCoreState() {
876	  STEPS.forEach(function (st) { state.status[st.id] = "locked"; });
877	  state.currentIdx = 0;
878	  state.intercepts = 0;
879	  state.undoCount = 0;
880	  state.confirmCount = 0;
881	  state.checked = {};
882	  state.observed = {};
883	  state.armedStepId = null;
884	  state.armedRemain = 0;
885	  state.finished = false;
886	  state.startedAt = performance.now();
887	  state.finishedAt = 0;
888	  refreshOrderStatuses();
889	}
890	
891	function buildAll() {
892	  buildPhaseNav();
893	  buildStepList();
894	  auditFeedEl.innerHTML = "";
895	  summarySlotEl.innerHTML = "";
896	  audit("system", "发布窗口开启：流程就绪，共 " + TOTAL + " 步（含 " + IRREVERSIBLE_COUNT + " 步不可逆操作）");
897	  renderAll();
898	}
899	
900	function resetAll() {
901	  resetCoreState();
902	  buildAll();
903	  toast("演练已重置：流程回到初始就绪态", false);
904	  const first = cardRefs[STEPS[0].id];
905	  if (first && first.checkInputs[0]) first.checkInputs[0].focus({ preventScroll: true });
906	}
907	
908	/* 全局时钟：演练用时 + 恢复窗口倒计时 */
909	setInterval(function () {
910	  elapsedEl.textContent = fmtClock(elapsedMs());
911	  if (state.armedStepId) {
912	    state.armedRemain = Math.max(0, state.armedRemain - 0.1);
913	    const ref = cardRefs[state.armedStepId];
914	    if (ref && ref.remainText) {
915	      ref.remainText.textContent = "剩余 " + state.armedRemain.toFixed(1) + " 秒";
916	      const step = STEPS.filter(function (s) { return s.id === state.armedStepId; })[0];
917	      if (step && ref.remainBar) {
918	        ref.remainBar.style.width = (state.armedRemain / step.recoverySeconds * 100) + "%";
919	      }
920	    }
921	    if (state.armedRemain <= 0) settleArmed();
922	  }
923	}, 100);
924	
925	resetBtn.addEventListener("click", openResetModal);
926	
927	/* 启动：初始数据内联，脚本执行完毕即完成首屏渲染（就绪态） */
928	resetCoreState();
929	buildAll();
930	
931	/* ========== 演示钩子：?demo=… 驱动与真实交互完全相同的代码路径，
932	   供截图取证与验收测量使用；正常使用不受影响。 ========== */
933	function demoHook() {
934	  const mode = new URLSearchParams(location.search).get("demo");
935	  if (!mode) return;
936	  const byId = function (id) { return STEPS.filter(function (s) { return s.id === id; })[0]; };
937	  if (mode === "confirm") {
938	    openConfirmModal(byId("s6"));
939	  } else if (mode === "armed") {
940	    executeIrreversible(byId("s6"));
941	  } else if (mode === "intercept") {
942	    intercept(byId("s4"), "顺序守卫：需先完成「" + byId("s1").title + "」");
943	  } else if (mode === "done") {
944	    STEPS.forEach(function (st) {
945	      if (st.kind === "check") {
946	        state.checked[st.id] = {};
947	        st.checks.forEach(function (_t, i) { state.checked[st.id][i] = true; });
948	        if (st.observe) state.observed[st.id] = true;
949	      }
950	      if (st.kind === "irreversible") {
951	        state.confirmCount++;
952	        state.status[st.id] = "done";
953	        audit("confirm", "确认执行：" + st.title + "（变更单 " + FLOW.ticket + "）");
954	        audit("done", st.settleText);
955	      } else {
956	        state.status[st.id] = "done";
957	        audit("done", "完成：" + st.title);
958	      }
959	    });
960	    refreshOrderStatuses();
961	    renderAll();
962	    if (state.finished) finishFlow();
963	  }
964	}
965	demoHook();
966	
967	})();
