          confirmExpect: "CHG-2417",
          recoverySeconds: 8,
          undoText: "已撤销：重新进入冻结状态（恢复窗口内回退）",
          settleText: "落定生效：版本 v2.7.0 已落定",
          rollbackPlan: "落定后回滚：执行 ROLLBACK-2417 全量预案并发布公告，预计 15 分钟恢复。"
        },
